      if (!Array.isArray(a) || !a.length) return 0;
      const sel = new Set(a), cor = new Set(q.answer); let err = 0;
      sel.forEach((x) => { if (!cor.has(x)) err++; }); cor.forEach((x) => { if (!sel.has(x)) err++; });
      return err === 0 ? 2 : err === 1 ? 1 : 0;
